function itemModal(ret='item',id=null){modalReturn=ret;const i=id?db.items.find(x=>x.id===id):normalizeItem({});editingIndex=id?db.items.findIndex(x=>x.id===id):-1;openModal(`${id?'Edit':'Create'} Medicine / Batch`,`<div class="actions"><button class="btn gray" type="button" onclick="catalogPicker()">📚 Select from Medicine Catalogue</button></div><div class="formgrid"><div class="field"><label>Product *</label><input id="mProduct" autofocus value="${esc(i.product)}"></div><div class="field"><label>Barcode</label><input id="mBarcode" value="${esc(i.barcode)}"></div><div class="field"><label>Company</label><input id="mCompany" value="${esc(i.company)}"></div><div class="field"><label>Salt / Composition</label><input id="mSalt" value="${esc(i.salt)}"></div><div class="field"><label>HSN / SAC</label><input id="mHSN" value="${esc(i.hsn)}"></div><div class="field"><label>Unit</label><select id="mUnit">${UNITS.map(u=>`<option ${i.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>Batch *</label><input id="mBatch" value="${esc(i.batch)}"></div><div class="field"><label>Expiry MM/YYYY</label><input id="mExp" placeholder="12/2027" value="${esc(i.exp)}"></div><div class="field"><label>Pack (units/strip)</label><input id="mPack" type="number" min="1" value="${i.pack}"></div><div class="field"><label>MRP / Strip *</label><input id="mMRP" type="number" min="0" step="0.01" value="${i.mrp}"></div><div class="field"><label>Purchase Rate / Strip</label><input id="mRate" type="number" min="0" step="0.01" value="${i.rate}"></div><div class="field"><label>GST %</label><select id="mGST">${GST.map(g=>`<option value="${g}" ${num(i.gst)===g?'selected':''}>${g}%</option>`).join('')}</select></div><div class="field"><label>Opening Stock (units)</label><input id="mStock" type="number" min="0" value="${i.stock}"></div><div class="field"><label>Rack</label><input id="mRack" value="${esc(i.rack)}"></div><div class="field"><label>Reorder Level</label><input id="mReorder" type="number" min="0" value="${i.reorder}"></div></div><div class="actions"><button class="btn green" onclick="saveItem()">Save Item</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`)}

function catalogPicker(){
  openModal('Medicine Catalogue',`<div class="note"><b>Mega Catalogue:</b> Search the 251K+ medicine master by product, company or salt. Select a catalogue item to fill the Item Master form. Batch, expiry, MRP, purchase rate and opening stock remain for your store to enter.</div><div class="field"><label>Search medicine / salt / company</label><input id="catQ" autofocus placeholder="e.g. paracetamol, amoxicillin, azithromycin" oninput="renderCatalog(this.value)"></div><div id="catStatus" class="muted" style="margin-top:8px">Loading catalogue…</div><div id="catResults" class="scroll" style="margin-top:10px;max-height:55vh"></div>`);
  renderCatalog('');
}
function parseCSVLine(line){
  const out=[]; let cur='', quoted=false;
  for(let i=0;i<line.length;i++){
    const c=line[i];
    if(c==='"'){
      if(quoted && line[i+1]==='"'){cur+='"';i++;}
      else quoted=!quoted;
    }else if(c===',' && !quoted){out.push(cur);cur='';}
    else cur+=c;
  }
  out.push(cur); return out;
}
async function loadMegaCatalogue(){
  if(window.rishuMegaCatalog)return window.rishuMegaCatalog;
  if(window.rishuMegaLoading)return window.rishuMegaLoading;
  window.rishuMegaLoading=(async()=>{
    const files=['medicine_catalogue_part1.csv','medicine_catalogue_part2.csv','medicine_catalogue_part3.csv','medicine_catalogue_part4.csv'];
    const rows=[];
    for(const file of files){
      const r=await fetch('./'+file,{cache:'no-store'});
      if(!r.ok)throw new Error(file+' not found ('+r.status+').');
      const text=await r.text();
      const lines=text.split(/\r?\n/);
      if(!lines.length)continue;
      const header=parseCSVLine(lines[0]);
      const idx={}; header.forEach((h,i)=>idx[h.trim()]=i);
      for(let i=1;i<lines.length;i++){
        const line=lines[i]; if(!line.trim())continue;
        const a=parseCSVLine(line);
        const product=a[idx.product]||''; if(!product)continue;
        rows.push({product,company:a[idx.company]||'',salt:a[idx.salt]||'',dosage_form:a[idx.dosage_form]||'',pack:a[idx.pack]||'',reference_price:a[idx.reference_price]||'',discontinued:a[idx.discontinued]||''});
      }
    }
    window.rishuMegaCatalog=rows; return rows;
  })().catch(e=>{window.rishuMegaLoading=null;throw e;});
  return window.rishuMegaLoading;
}
async function renderCatalog(q=''){
  const box=$('catResults'),status=$('catStatus'); if(!box)return;
  q=String(q||'').trim().toLowerCase();
  try{
    if(status)status.textContent='Loading 251K+ catalogue…';
    const data=await loadMegaCatalogue();
    const terms=q.split(/\s+/).filter(Boolean);
    const rows=data.filter(x=>!terms.length||terms.every(t=>(x.product+' '+x.company+' '+x.salt+' '+x.dosage_form+' '+x.pack).toLowerCase().includes(t))).slice(0,50);
    if(status)status.textContent=`${data.length.toLocaleString('en-IN')} catalogue records loaded • showing ${rows.length}`;
    box.innerHTML=rows.map((x,n)=>`<div class="card" style="margin:8px 0;padding:12px"><b>${esc(x.product)}</b><div class="muted">${esc(x.salt||'')} • ${esc(x.company||'')} • ${esc(x.dosage_form||'')} • Pack ${esc(x.pack||'')}</div><button class="btn gray" type="button" onclick="selectCatalog(${n})">Select</button></div>`).join('')||'<div class="empty">No catalogue item found.</div>';
    window.rishuCatalogFiltered=rows;
  }catch(e){if(status)status.textContent='Catalogue load failed';box.innerHTML='<div class="danger">Could not load the mega catalogue: '+esc(e.message||'unknown error')+'</div>';}
}
function selectCatalog(n){
  const x=(window.rishuCatalogFiltered||[])[n]; if(!x)return;
  closeModal();
  itemModal(modalReturn, null);
  $('mProduct').value=x.product||''; $('mBarcode').value=x.barcode||''; $('mCompany').value=x.company||''; $('mSalt').value=x.salt||''; $('mHSN').value=x.hsn||''; $('mUnit').value=x.unit||'Tablet'; $('mPack').value=x.pack||1; $('mGST').value=x.gst??0;
  $('mBatch').focus();
}
function saveItem(){const product=$('mProduct').value.trim(),batch=$('mBatch').value.trim();if(!product||!batch)return alert('Product and Batch are required.');const id=editingIndex>=0?db.items[editingIndex].id:cryptoRandom(),i=normalizeItem({id,product,barcode:$('mBarcode').value.trim(),company:$('mCompany').value.trim(),salt:$('mSalt').value.trim(),hsn:$('mHSN').value.trim(),unit:$('mUnit').value,batch,exp:$('mExp').value.trim(),pack:num($('mPack').value)||1,mrp:num($('mMRP').value),rate:num($('mRate').value),gst:num($('mGST').value),stock:num($('mStock').value),rack:$('mRack').value.trim(),reorder:num($('mReorder').value)||10});if(db.items.some((x,j)=>j!==editingIndex&&x.product.toLowerCase()===product.toLowerCase()&&x.batch.toLowerCase()===batch.toLowerCase()))return alert('This Product + Batch already exists.');if(editingIndex<0)db.items.push(i);else db.items[editingIndex]=i;save();closeModal();if(modalReturn==='sale'){sale();saleRows.push({...i,stripQty:1,looseQty:0,discount:0});renderSale()}else if(modalReturn==='purchase'){purchase();purchaseRows.push({...i,pqty:1,freeQty:0,prate:i.rate,pdisc:0});renderPurchase()}else show(modalReturn||'item')}
function editItem(id){itemModal('item',id)}
function deleteItem(id){const i=db.items.findIndex(x=>x.id===id);if(i<0)return;if(!confirm('Delete this item/batch? Existing bills remain safe.'))return;db.items.splice(i,1);save();item()}
function stock(){const low=db.items.filter(i=>num(i.stock)<=num(i.reorder));$('app').innerHTML=layout('Stock',`<button class="btn" onclick="stockAdjustModal()">± Stock Adjustment</button>`)+`<div class="card"><h3>Batch-wise Stock</h3><input id="stockQ" placeholder="Search product / batch / rack" oninput="renderStock(this.value)"><div id="stockData"></div></div><div class="card"><h3>Low Stock</h3>${low.map(i=>`<div class="danger">⚠ ${esc(i.product)} • ${esc(i.batch)} • ${i.stock} units</div>`).join('')||'<div class="muted">No low-stock items.</div>'}</div>`;renderStock('')}
function renderStock(q){q=(q||'').toLowerCase();const rows=db.items.filter(i=>(i.product+' '+i.batch+' '+i.barcode+' '+i.rack).toLowerCase().includes(q));$('stockData').innerHTML=`<div class="scroll"><table><tr><th>Product</th><th>Batch</th><th>Expiry</th><th>Pack</th><th>Stock Units</th><th>Strips</th><th>MRP</th><th>Purchase Rate</th><th>GST</th><th>Rack</th></tr>${rows.map(i=>`<tr><td>${esc(i.product)}</td><td>${esc(i.batch)}</td><td>${esc(i.exp)}</td><td>${i.pack}</td><td><b>${i.stock}</b></td><td>${(num(i.stock)/Math.max(1,num(i.pack))).toFixed(2)}</td><td>${money(i.mrp)}</td><td>${money(i.rate)}</td><td>${i.gst}%</td><td>${esc(i.rack)}</td></tr>`).join('')||'<tr><td colspan="10">No stock.</td></tr>'}</table></div>`}
function stockAdjustModal(){openModal('Stock Adjustment',`<div class="formgrid"><div class="field wide"><label>Product / Batch *</label><select id="adjItem">${db.items.map(i=>`<option value="${esc(i.id)}">${esc(i.product)} • ${esc(i.batch)} • Stock ${i.stock}</option>`).join('')}</select></div><div class="field"><label>Adjustment Units</label><input id="adjQty" type="number" step="1" value="0"></div><div class="field wide"><label>Reason</label><input id="adjReason" placeholder="Damage / Opening correction / Physical count"></div></div><div class="actions"><button class="btn green" onclick="adjustStock()">Save Adjustment</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`)}
function adjustStock(){const it=db.items.find(i=>i.id===$('adjItem').value),q=Math.trunc(num($('adjQty').value));if(!it||!q)return alert('Enter valid adjustment.');if(num(it.stock)+q<0)return alert('Stock cannot go below zero.');it.stock+=q;save();closeModal();stock()}
