function purchaseTable(){return `<div class="scroll"><table><tr><th>Invoice</th><th>Date</th><th>Supplier</th><th>Taxable</th><th>GST</th><th>Total</th><th>Paid</th><th>Balance</th><th>Action</th></tr>${db.purchases.map((p,i)=>`<tr><td>${esc(p.no)}</td><td>${esc(p.date)}</td><td>${esc(p.supplier)}</td><td>${money(p.taxable)}</td><td>${money(p.tax)}</td><td><b>${money(p.total)}</b></td><td>${money(p.paid)}</td><td>${money(p.balance)}</td><td><button class="btn gray" onclick="printPurchase(db.purchases[${i}])">🖨 Reprint</button></td></tr>`).join('')||'<tr><td colspan="9">No purchases.</td></tr>'}</table></div>`}
