function dayBook(){const rows=[...db.sales.map(x=>({date:x.date,doc:x.no,type:'Sale',party:x.party,amount:x.net})),...db.purchases.map(x=>({date:x.date,doc:x.no,type:'Purchase',party:x.supplier,amount:x.total}))].sort((a,b)=>String(a.date).localeCompare(String(b.date)));$('reportArea').innerHTML=`<h3>Day Book</h3><div class="scroll"><table><tr><th>Date</th><th>Document</th><th>Type</th><th>Party</th><th>Amount</th></tr>${rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.doc)}</td><td>${r.type}</td><td>${esc(r.party)}</td><td>${money(r.amount)}</td></tr>`).join('')||'<tr><td colspan="5">No transactions.</td></tr>'}</table></div>`}
function ledger(){const names=[...new Set([...db.parties.map(p=>p.name),...db.sales.map(s=>s.party),...db.purchases.map(p=>p.supplier)])].filter(Boolean);$('reportArea').innerHTML=`<h3>Party Ledger</h3><select id="ledgerParty" style="width:100%;padding:11px" onchange="renderLedger()"><option value="">Select Party</option>${names.map(n=>`<option>${esc(n)}</option>`).join('')}</select><div id="ledgerData"></div>`}
function renderLedger(){const n=$('ledgerParty').value;if(!n)return;let bal=0;const rows=[...db.sales.filter(x=>x.party===n).map(x=>({date:x.date,doc:x.no,type:'Sale',debit:num(x.net),credit:0})),...db.purchases.filter(x=>x.supplier===n).map(x=>({date:x.date,doc:x.no,type:'Purchase',debit:0,credit:num(x.total)}))].sort((a,b)=>String(a.date).localeCompare(String(b.date)));$('ledgerData').innerHTML=`<div class="scroll"><table><tr><th>Date</th><th>Doc</th><th>Type</th><th>Debit</th><th>Credit</th><th>Balance</th></tr>${rows.map(r=>{bal+=r.debit-r.credit;return `<tr><td>${esc(r.date)}</td><td>${esc(r.doc)}</td><td>${r.type}</td><td>${money(r.debit)}</td><td>${money(r.credit)}</td><td>${money(bal)}</td></tr>`}).join('')||'<tr><td colspan="6">No transactions.</td></tr>'}</table></div>`}
function stockLedger(){ $('reportArea').innerHTML=`<h3>Stock Ledger</h3><div class="field"><label>Search</label><input oninput="renderStockLedger(this.value)"></div><div id="stockLedgerData"></div>`;renderStockLedger('')}
function renderStockLedger(q){q=(q||'').toLowerCase();const rows=db.items.filter(i=>(i.product+' '+i.batch+' '+i.barcode).toLowerCase().includes(q));$('stockLedgerData').innerHTML=`<div class="scroll"><table><tr><th>Product</th><th>Batch</th><th>Expiry</th><th>Units</th><th>Strips</th><th>MRP</th><th>Rack</th></tr>${rows.map(i=>`<tr><td>${esc(i.product)}</td><td>${esc(i.batch)}</td><td>${esc(i.exp)}</td><td>${i.stock}</td><td>${(num(i.stock)/Math.max(1,num(i.pack))).toFixed(2)}</td><td>${money(i.mrp)}</td><td>${esc(i.rack)}</td></tr>`).join('')||'<tr><td colspan="7">No stock.</td></tr>'}</table></div>`}
function nearExpiryCount(){const now=new Date(),lim=new Date(now.getFullYear(),now.getMonth()+6,1);return db.items.filter(i=>{const m=String(i.exp).match(/^(\d{1,2})[\/-](\d{4})$/);if(!m)return false;const d=new Date(+m[2],+m[1]-1,1);return d>=new Date(now.getFullYear(),now.getMonth(),1)&&d<=lim}).length}
function expiryReport(){const now=new Date(),lim=new Date(now.getFullYear(),now.getMonth()+6,1),rows=db.items.filter(i=>{const m=String(i.exp).match(/^(\d{1,2})[\/-](\d{4})$/);if(!m)return false;const d=new Date(+m[2],+m[1]-1,1);return d>=new Date(now.getFullYear(),now.getMonth(),1)&&d<=lim}).sort((a,b)=>String(a.exp).localeCompare(String(b.exp)));$('reportArea').innerHTML=`<h3>Expiry Report • Next 6 Months</h3><div class="scroll"><table><tr><th>Product</th><th>Batch</th><th>Expiry</th><th>Stock</th><th>MRP</th><th>Rack</th></tr>${rows.map(i=>`<tr><td>${esc(i.product)}</td><td>${esc(i.batch)}</td><td>${esc(i.exp)}</td><td>${i.stock}</td><td>${money(i.mrp)}</td><td>${esc(i.rack)}</td></tr>`).join('')||'<tr><td colspan="6">No near-expiry batches.</td></tr>'}</table></div>`}
function printSale(b){const s=shop(),cg=b.mode==='local'?b.tax/2:0,sg=cg,ig=b.mode==='inter'?b.tax:0,w=window.open('','_blank');if(!w)return alert('Allow pop-ups for printing.');w.document.write(printHtml('TAX INVOICE',b,s,`<th>Qty</th><th>MRP</th>`,x=>`<td>${x.qty}</td><td>${money(x.mrp)}</td>`,cg,sg,ig,false));w.document.close()}
function printPurchase(b){const s=shop(),cg=b.mode==='local'?b.tax/2:0,sg=cg,ig=b.mode==='inter'?b.tax:0,w=window.open('','_blank');if(!w)return alert('Allow pop-ups for printing.');w.document.write(printHtml('PURCHASE INVOICE',b,s,`<th>Qty</th><th>Free</th><th>Rate</th><th>MRP</th>`,x=>`<td>${x.qty}</td><td>${x.free||0}</td><td>${money(x.prate)}</td><td>${money(x.mrp)}</td>`,cg,sg,ig,true));w.document.close()}
function printHtml(title,b,s,head,cellsFn,cg,sg,ig,purchase=false){return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(b.no)}</title><style>body{font-family:Arial,sans-serif;color:#111;padding:24px;font-size:12px}h1{text-align:center;margin:0;font-size:22px}h3{text-align:center;margin:5px 0 14px}hr{border:0;border-top:1px solid #222}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{border:1px solid #222;padding:6px}th{background:#eee}.r{text-align:right}.tot{width:46%;margin-left:auto;margin-top:10px}.row{display:flex;justify-content:space-between;padding:4px}.net{border-top:2px solid #111;font-weight:800;font-size:15px;padding-top:8px}.small{font-size:11px}</style></head><body><h1>${esc(s.name)}</h1><h3>${title}</h3><div style="text-align:center">Retail Pharmacy • GST • Batch • Strip/Loose<br>${esc(s.address)} • Mob. ${esc(s.mobile)}</div><hr><b>${purchase?'Invoice':'Bill'} No.:</b> ${esc(b.no)} &nbsp;&nbsp; <b>Date:</b> ${esc(b.date)} &nbsp;&nbsp; <b>${purchase?'Supplier':'Customer'}:</b> ${esc(purchase?b.supplier:b.party)}<br>${!purchase?`<b>Mobile:</b> ${esc(b.mobile||'-')} &nbsp; <b>Doctor:</b> ${esc(b.doctor||'-')} &nbsp; <b>Rx No.:</b> ${esc(b.rx||'-')}<br>`:''}<b>Payment:</b> ${esc(b.payment||'-')} &nbsp; <b>GST Mode:</b> ${b.mode==='inter'?'Interstate • IGST':'Local • CGST + SGST'}<table><tr><th>#</th><th>Product</th><th>Batch</th><th>Expiry</th>${head}<th>GST</th><th>Amount</th></tr>${(b.lines||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.product)}</td><td>${esc(x.batch)}</td><td>${esc(x.exp)}</td>${cellsFn(x)}<td>${x.gst}%</td><td class="r">${money(purchase?x.total2:(x.after+x.tax))}</td></tr>`).join('')}</table><div class="tot"><div class="row"><span>${purchase?'Gross Purchase':'Subtotal'}</span><span>${money(purchase?b.gross:b.subtotal)}</span></div><div class="row"><span>Discount</span><span>${money(b.discount)}</span></div><div class="row"><span>Taxable Value</span><span>${money(b.taxable)}</span></div><div class="row"><span>CGST</span><span>${money(cg)}</span></div><div class="row"><span>SGST</span><span>${money(sg)}</span></div><div class="row"><span>IGST</span><span>${money(ig)}</span></div>${purchase?`<div class="row"><span>Round Off</span><span>${money(b.round)}</span></div>`:''}<div class="row net"><span>NET PAYABLE</span><span>${money(b.net||b.total)}</span></div>${purchase?`<div class="row"><span>Paid</span><span>${money(b.paid)}</span></div><div class="row"><span>Balance</span><span>${money(b.balance)}</span></div>`:''}</div><p><b>Amount in Words:</b> ${esc(inWords(b.net||b.total))}</p><p class="small">Terms: Please check medicine, batch and expiry before leaving the counter.</p><p style="margin-top:55px;text-align:right">Authorized Signature</p><script>window.print()</script></body></html>`}
function inWords(n){n=Math.round(num(n));if(n===0)return 'Zero Rupees only';const o=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],t=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const two=x=>x<20?o[x]:t[Math.floor(x/10)]+(x%10?' '+o[x%10]:'');let r='';if(n>=10000000){r+=two(Math.floor(n/10000000))+' Crore ';n%=10000000}if(n>=100000){r+=two(Math.floor(n/100000))+' Lakh ';n%=100000}if(n>=1000){r+=two(Math.floor(n/1000))+' Thousand ';n%=1000}if(n>=100){r+=o[Math.floor(n/100)]+' Hundred ';n%=100}if(n)r+=(r?'and ':'')+two(n)+' ';return r.trim()+' Rupees only'}
function previewSale(){const c=saleCalc();if(!c.lines.length)return alert('Add item first.');const temp={no:'PREVIEW',date:new Date().toLocaleString('en-IN'),party:$('saleParty').value||'Cash Customer',mobile:$('saleMobile').value,doctor:$('saleDoctor').value,rx:$('saleRx').value,payment:$('salePay').value,mode:$('saleGst').value,subtotal:c.subtotal,discount:c.itemDiscount+c.billDisc,taxable:c.taxable,tax:c.tax,net:c.net,lines:c.lines};printSale(temp)}
function previewPurchase(){const c=purchaseCalc();if(!c.lines.length)return alert('Add item first.');const temp={no:$('pInvoice').value||'PREVIEW',date:$('pDate').value,supplier:$('pSupplier').value||'-',payment:$('pPay').value,mode:$('pGst').value,gross:c.gross,discount:c.itemDisc+c.billDisc,taxable:c.taxable,tax:c.tax,round:c.round,total:c.total,paid:c.paid,balance:c.balance,lines:c.lines};printPurchase(temp)}
function shareWhatsApp(i){const b=db.sales[i],txt=`${shop().name}\nBill: ${b.no}\nCustomer: ${b.party}\n${(b.lines||[]).map((x,j)=>`${j+1}. ${x.product} • ${x.batch} • Qty ${x.qty} • ${money(x.mrp)}`).join('\n')}\nNET: ${money(b.net)}`;window.open('https://wa.me/?text='+encodeURIComponent(txt),'_blank')}

function doctorOpts(selected=''){return `<option value="">Select Doctor</option>`+db.doctors.map(d=>`<option value="${esc(d.name)}" ${d.name===selected?'selected':''}>${esc(d.name)}${d.specialization?' • '+esc(d.specialization):''}</option>`).join('')}
function doctors(){
  $('app').innerHTML=layout('Doctor Master',`<button class="btn" onclick="doctorModal()">+ New Doctor</button>`)+`<div class="card"><div class="field"><label>Search Doctor</label><input id="doctorFilter" placeholder="Name / specialization / mobile" oninput="renderDoctors()"></div></div><div class="card"><div class="scroll"><table><thead><tr><th>Doctor</th><th>Specialization</th><th>Mobile</th><th>Clinic</th><th>Reg. No.</th><th>Action</th></tr></thead><tbody id="doctorBody"></tbody></table></div></div>`;renderDoctors()
}
function renderDoctors(){const q=($('doctorFilter')?.value||'').toLowerCase();const rows=db.doctors.filter(d=>(d.name+' '+d.specialization+' '+d.mobile+' '+d.clinic+' '+d.reg).toLowerCase().includes(q));$('doctorBody').innerHTML=rows.map(d=>`<tr><td><b>${esc(d.name)}</b></td><td>${esc(d.specialization||'-')}</td><td>${esc(d.mobile||'-')}</td><td>${esc(d.clinic||'-')}</td><td>${esc(d.reg||'-')}</td><td><button class="btn gray" onclick="doctorModal('${esc(d.id)}')">Edit</button> <button class="btn red" onclick="deleteDoctor('${esc(d.id)}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="6">No doctors.</td></tr>'}
function doctorModal(id=''){const d=db.doctors.find(x=>x.id===id)||{};openModal(id?'Edit Doctor':'New Doctor',`<div class="formgrid"><div class="field wide"><label>Doctor Name *</label><input id="dName" value="${esc(d.name)}" autofocus></div><div class="field"><label>Specialization</label><input id="dSpec" value="${esc(d.specialization)}"></div><div class="field"><label>Mobile</label><input id="dMobile" value="${esc(d.mobile)}"></div><div class="field wide"><label>Clinic / Hospital</label><input id="dClinic" value="${esc(d.clinic)}"></div><div class="field"><label>Registration No.</label><input id="dReg" value="${esc(d.reg)}"></div></div><div class="actions"><button class="btn" onclick="saveDoctor('${esc(id)}')">Save Doctor</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`) }
function saveDoctor(id=''){const name=$('dName').value.trim();if(!name)return alert('Doctor name required.');const obj={id:id||cryptoRandom(),name,specialization:$('dSpec').value.trim(),mobile:$('dMobile').value.trim(),clinic:$('dClinic').value.trim(),reg:$('dReg').value.trim()};const ix=db.doctors.findIndex(x=>x.id===id);if(ix>=0)db.doctors[ix]=obj;else db.doctors.push(obj);save();closeModal();doctors()}
function deleteDoctor(id){if(!confirm('Delete this doctor?'))return;db.doctors=db.doctors.filter(x=>x.id!==id);save();doctors()}
function expenses(){ $('app').innerHTML=layout('Expenses',`<button class="btn" onclick="expenseModal()">+ Add Expense</button>`)+`<div class="card"><div class="scroll"><table><thead><tr><th>Date</th><th>Category</th><th>Note</th><th>Amount</th><th>Action</th></tr></thead><tbody>${db.expenses.map((e,i)=>`<tr><td>${esc(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.note||'-')}</td><td>${money(e.amount)}</td><td><button class="btn red" onclick="deleteExpense(${i})">Delete</button></td></tr>`).join('')||'<tr><td colspan="5">No expenses.</td></tr>'}</tbody></table></div></div>`}
function expenseModal(){openModal('Add Expense',`<div class="formgrid"><div class="field"><label>Date</label><input id="eDate" type="date" value="${today()}"></div><div class="field"><label>Category</label><select id="eCat"><option>Rent</option><option>Electricity</option><option>Salary</option><option>Transport</option><option>Miscellaneous</option></select></div><div class="field wide"><label>Note</label><input id="eNote"></div><div class="field"><label>Amount ₹ *</label><input id="eAmount" type="number" min="0" step="0.01"></div></div><div class="actions"><button class="btn" onclick="saveExpense()">Save Expense</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`)}
function saveExpense(){const amount=num($('eAmount').value);if(amount<=0)return alert('Enter valid amount.');db.expenses.push({id:cryptoRandom(),date:$('eDate').value,category:$('eCat').value,note:$('eNote').value.trim(),amount});save();closeModal();expenses()}
function deleteExpense(i){if(confirm('Delete expense?')){db.expenses.splice(i,1);save();expenses()}}
function smartInsights(){const low=db.items.filter(i=>num(i.stock)<=num(i.reorder));const exp=db.items.filter(i=>isNearExpiry(i,90));const dead=db.items.filter(i=>num(i.stock)>0&&!db.sales.some(s=>(s.lines||[]).some(l=>l.id===i.id))).slice(0,10);const sold=new Map();db.sales.forEach(s=>(s.lines||[]).forEach(l=>sold.set(l.id,(sold.get(l.id)||0)+num(l.qty))));const fast=db.items.map(i=>({...i,sold:sold.get(i.id)||0})).sort((a,b)=>b.sold-a.sold).slice(0,5);return {low,exp,dead,fast}}
function isNearExpiry(exp,days){const m=String(exp.exp||'').match(/^(\d{1,2})[\/-](\d{4})$/);if(!m)return false;const d=new Date(+m[2],+m[1]-1,1),lim=new Date();lim.setDate(lim.getDate()+days);return d>=new Date(new Date().getFullYear(),new Date().getMonth(),1)&&d<=lim}
function dashboardV10(){const d=today(),sales=db.sales.filter(x=>String(x.date||'').slice(0,10)===d),saleTotal=sales.reduce((a,x)=>a+num(x.net),0),purchaseTotal=db.purchases.filter(x=>String(x.date||'').slice(0,10)===d).reduce((a,x)=>a+num(x.total),0),expenseTotal=db.expenses.filter(x=>String(x.date||'').slice(0,10)===d).reduce((a,x)=>a+num(x.amount),0),ins=smartInsights();$('app').innerHTML=layout('Dashboard',`<button class="btn" onclick="show('sale')">F2 • New Sale</button>`)+`<div class="grid"><div class="stat"><small>Today's Sale</small><b>${money(saleTotal)}</b></div><div class="stat"><small>Today's Purchase</small><b>${money(purchaseTotal)}</b></div><div class="stat"><small>Today's Expenses</small><b>${money(expenseTotal)}</b></div><div class="stat"><small>Net Cash Movement</small><b>${money(saleTotal-purchaseTotal-expenseTotal)}</b></div></div><div class="grid"><div class="stat"><small>Items / Batches</small><b>${db.items.length}</b></div><div class="stat"><small>Low Stock</small><b>${ins.low.length}</b></div><div class="stat"><small>Expiry ≤ 90 Days</small><b>${ins.exp.length}</b></div><div class="stat"><small>Doctors</small><b>${db.doctors.length}</b></div></div><div class="grid"><div class="card"><h3>🤖 Smart Purchase Suggestions</h3>${ins.low.slice(0,12).map(x=>`<div class="alertrow">🛒 <b>${esc(x.product)}</b> • Batch ${esc(x.batch)} • Stock ${x.stock} • Reorder ${x.reorder}</div>`).join('')||'<div class="muted">No urgent purchase suggestions.</div>'}</div><div class="card"><h3>⏳ Expiry Watch</h3>${ins.exp.slice(0,12).map(x=>`<div class="danger">⚠ ${esc(x.product)} • ${esc(x.batch)} • Exp ${esc(x.exp)} • Stock ${x.stock}</div>`).join('')||'<div class="muted">No near-expiry batches.</div>'}</div></div><div class="card"><h3>🔥 Fast Moving Items</h3><div class="scroll"><table><tr><th>Product</th><th>Batch</th><th>Sold Units</th><th>Current Stock</th></tr>${ins.fast.map(x=>`<tr><td>${esc(x.product)}</td><td>${esc(x.batch)}</td><td>${x.sold}</td><td>${x.stock}</td></tr>`).join('')||'<tr><td colspan="4">No sales yet.</td></tr>'}</table></div></div><div class="card"><h3>Quick Menu</h3><div class="actions"><button class="btn" onclick="show('sale')">🧾 Retail Sale</button><button class="btn gray" onclick="show('purchase')">🛒 Purchase</button><button class="btn gray" onclick="show('item')">💊 Item Master</button><button class="btn gray" onclick="show('stock')">📦 Stock</button><button class="btn gray" onclick="show('doctors')">👨‍⚕️ Doctors</button><button class="btn gray" onclick="show('expenses')">💸 Expenses</button><button class="btn gray" onclick="show('reports')">📊 Reports</button><button class="btn gray" onclick="show('backup')">💾 Backup</button></div></div>`}

function can(role){const u=window.currentUser;return u&&(u.role==='Admin'||u.role===role||role==='Staff')}
function purchaseOrders(){if(!can('Staff'))return alert('Permission denied.');const rows=db.purchaseOrders||[];$('app').innerHTML=layout('Purchase Orders',`<button class="btn" onclick="purchaseOrderModal()">+ New Purchase Order</button>`)+`<div class="card"><div class="scroll"><table><thead><tr><th>PO No.</th><th>Date</th><th>Supplier</th><th>Items</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${rows.map((p,i)=>`<tr><td>${esc(p.no)}</td><td>${esc(p.date)}</td><td>${esc(p.supplier)}</td><td>${p.lines?.length||0}</td><td>${money(p.total)}</td><td><span class="badge">${esc(p.status||'Open')}</span></td><td><button class="btn gray" onclick="printPO(${i})">Print</button> <button class="btn gray" onclick="deletePO(${i})">Delete</button></td></tr>`).join('')||'<tr><td colspan="7">No purchase orders.</td></tr>'}</tbody></table></div></div>`}
function purchaseOrderModal(){openModal('New Purchase Order',`<div class="formgrid"><div class="field"><label>Supplier</label><select id="poSupplier">${partyOpts('Supplier')}</select></div><div class="field"><label>Date</label><input id="poDate" type="date" value="${today()}"></div><div class="field wide"><label>Items (Product | Qty | Rate)</label><textarea id="poLines" rows="8" placeholder="Paracetamol 500 | 10 | 25\nAmoxicillin 500 | 5 | 80"></textarea></div><div class="field"><label>Status</label><select id="poStatus"><option>Open</option><option>Sent</option><option>Received</option><option>Cancelled</option></select></div></div><div class="actions"><button class="btn" onclick="savePO()">Save PO</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`)}
function savePO(){const supplier=$('poSupplier').value;if(!supplier)return alert('Select supplier.');const lines=($('poLines').value||'').split('\n').map(x=>x.split('|').map(v=>v.trim())).filter(x=>x[0]);const clean=lines.map(x=>({product:x[0],qty:num(x[1]),rate:num(x[2])})).filter(x=>x.product&&x.qty>0);if(!clean.length)return alert('Add at least one valid line.');const no='PO'+String(1001+(db.purchaseOrders?.length||0));const total=clean.reduce((a,x)=>a+x.qty*x.rate,0);db.purchaseOrders.push({id:cryptoRandom(),no,date:$('poDate').value,supplier,status:$('poStatus').value,lines:clean,total});save();closeModal();purchaseOrders()}
function deletePO(i){if(confirm('Delete purchase order?')){db.purchaseOrders.splice(i,1);save();purchaseOrders()}}
function printPO(i){const p=db.purchaseOrders[i],s=shop();printHtml(`<h1>${esc(s.name)}</h1><p>${esc(s.address)} • ${esc(s.mobile)}</p><h2>PURCHASE ORDER</h2><p><b>PO:</b> ${esc(p.no)} &nbsp; <b>Date:</b> ${esc(p.date)} &nbsp; <b>Supplier:</b> ${esc(p.supplier)}</p><table><tr><th>#</th><th>Product</th><th>Qty</th><th>Rate</th><th>Amount</th></tr>${p.lines.map((l,j)=>`<tr><td>${j+1}</td><td>${esc(l.product)}</td><td>${l.qty}</td><td>${money(l.rate)}</td><td>${money(l.qty*l.rate)}</td></tr>`).join('')}</table><h3>Total: ${money(p.total)}</h3>`)}
function accounting(){const sales=db.sales.reduce((a,x)=>a+num(x.net),0),purch=db.purchases.reduce((a,x)=>a+num(x.total),0),exp=db.expenses.reduce((a,x)=>a+num(x.amount),0),cashSales=db.sales.filter(x=>x.payment!=='Credit').reduce((a,x)=>a+num(x.net),0),creditSales=db.sales.filter(x=>x.payment==='Credit').reduce((a,x)=>a+num(x.net),0),paidPurch=db.purchases.reduce((a,x)=>a+num(x.paid),0),duePurch=Math.max(0,purch-paidPurch),customerDue=Math.max(0,creditSales-(db.payments||[]).filter(x=>x.type==='Customer').reduce((a,x)=>a+num(x.amount),0));$('app').innerHTML=layout('Accounting & Ledger',`<button class="btn" onclick="paymentModal()">+ Receive / Pay</button>`)+`<div class="grid"><div class="stat"><small>Gross Sales</small><b>${money(sales)}</b></div><div class="stat"><small>Purchases</small><b>${money(purch)}</b></div><div class="stat"><small>Expenses</small><b>${money(exp)}</b></div><div class="stat"><small>Gross Movement</small><b>${money(sales-purch-exp)}</b></div></div><div class="grid"><div class="stat"><small>Cash/UPI Sales</small><b>${money(cashSales)}</b></div><div class="stat"><small>Customer Credit</small><b>${money(customerDue)}</b></div><div class="stat"><small>Supplier Payable</small><b>${money(duePurch)}</b></div><div class="stat"><small>Payments Entries</small><b>${(db.payments||[]).length}</b></div></div><div class="card"><h3>Recent Payments</h3><div class="scroll"><table><tr><th>Date</th><th>Type</th><th>Party</th><th>Mode</th><th>Amount</th><th>Note</th></tr>${(db.payments||[]).slice().reverse().slice(0,50).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.type)}</td><td>${esc(x.party)}</td><td>${esc(x.mode)}</td><td>${money(x.amount)}</td><td>${esc(x.note)}</td></tr>`).join('')||'<tr><td colspan="6">No payments.</td></tr>'}</table></div></div>`}
function paymentModal(){openModal('Receive / Pay',`<div class="formgrid"><div class="field"><label>Type</label><select id="payType"><option>Customer</option><option>Supplier</option><option>Expense</option></select></div><div class="field"><label>Date</label><input id="payDate" type="date" value="${today()}"></div><div class="field"><label>Party</label><input id="payParty" placeholder="Customer/Supplier"></div><div class="field"><label>Mode</label><select id="payMode"><option>Cash</option><option>UPI</option><option>Bank</option><option>Card</option></select></div><div class="field"><label>Amount ₹</label><input id="payAmount" type="number" min="0" step="0.01"></div><div class="field wide"><label>Note</label><input id="payNote"></div></div><div class="actions"><button class="btn" onclick="savePayment()">Save Entry</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`)}
function savePayment(){const amount=num($('payAmount').value);if(amount<=0)return alert('Enter valid amount.');db.payments.push({id:cryptoRandom(),date:$('payDate').value,type:$('payType').value,party:$('payParty').value.trim(),mode:$('payMode').value,amount,note:$('payNote').value.trim()});save();closeModal();accounting()}
function users(){if(!can('Admin'))return alert('Admin only.');$('app').innerHTML=layout('Users & Permissions',`<button class="btn" onclick="userModal()">+ New User</button>`)+`<div class="card"><div class="scroll"><table><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th></th></tr>${db.users.map((u,i)=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${u.active?'Active':'Disabled'}</td><td>${u.username==='admin'?'':`<button class="btn gray" onclick="deleteUser(${i})">Delete</button>`}</td></tr>`).join('')}</table></div></div>`}
function userModal(){openModal('Create User',`<div class="formgrid"><div class="field"><label>Name</label><input id="uName"></div><div class="field"><label>Username</label><input id="uUsername"></div><div class="field"><label>Password</label><input id="uPassword" type="password"></div><div class="field"><label>Role</label><select id="uRole"><option>Admin</option><option>Manager</option><option>Staff</option></select></div></div><div class="actions"><button class="btn" onclick="saveUser()">Create</button><button class="btn gray" onclick="closeModal()">Cancel</button></div>`)}
function saveUser(){const username=$('uUsername').value.trim();if(!username||!$('uPassword').value)return alert('Username and password required.');if(db.users.some(u=>u.username.toLowerCase()===username.toLowerCase()))return alert('Username already exists.');db.users.push({id:cryptoRandom(),name:$('uName').value.trim()||username,username,password:$('uPassword').value,role:$('uRole').value,active:true});save();closeModal();users()}
function deleteUser(i){if(confirm('Delete user?')){db.users.splice(i,1);save();users()}}
function login(){if(window.currentUser)return;const saved=sessionStorage.getItem('rishu_user');if(saved){try{const u=db.users.find(x=>x.username===saved);if(u&&u.active){window.currentUser=u;return}}catch{}}document.body.insertAdjacentHTML('afterbegin',`<div id="loginScreen" class="modal" style="display:flex"><div class="modalbox" style="max-width:420px"><div class="modalhead"><h2>🔐 Rishu ERP Login</h2></div><div class="field"><label>Username</label><input id="loginUser" value="admin" autocomplete="username"></div><div class="field"><label>Password</label><input id="loginPass" type="password" value="admin123" autocomplete="current-password"></div><div class="actions"><button class="btn" onclick="doLogin()">Login</button></div><p class="muted">First login: admin / admin123. Change credentials by creating users and deleting the default account when ready.</p></div></div>`)}
function doLogin(){const u=db.users.find(x=>x.username===$('loginUser').value.trim()&&x.password===$('loginPass').value&&x.active);if(!u)return alert('Invalid username/password.');window.currentUser=u;sessionStorage.setItem('rishu_user',u.username);$('loginScreen')?.remove();show('dashboard')}
function logout(){sessionStorage.removeItem('rishu_user');window.currentUser=null;location.reload()}
function backup(){$('app').innerHTML=layout('Backup & Restore')+`<div class="card"><h3>💾 Complete Data Protection</h3><p>Items, batches, parties, sales, purchases aur returns ka backup.</p><div class="actions"><button class="btn" onclick="downloadBackup()">⬇ Download Backup</button><button class="btn gray" onclick="$('restore').click()">⬆ Restore Backup</button><button class="btn gray" onclick="restoreAuto()">♻ Restore Auto Backup</button><input id="restore" type="file" accept=".json,application/json" hidden onchange="restoreFile(event)"></div></div><div class="grid">${[['Items',db.items.length],['Parties',db.parties.length],['Sales',db.sales.length],['Purchases',db.purchases.length]].map(x=>`<div class="stat"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div>`}
function downloadBackup(){download(`Rishu_Medical_Backup_${today()}.json`,JSON.stringify({app:'RISHU MEDICAL AND HEALTHCARE ERP',version:11,exportedAt:new Date().toISOString(),data:db},null,2),'application/json')}
function restoreFile(e){const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result),d=norm(x.data||x);if(!confirm(`Restore backup?\nItems ${d.items.length}\nParties ${d.parties.length}\nSales ${d.sales.length}\nPurchases ${d.purchases.length}\nCurrent data will be replaced.`))return;db=d;save();alert('Backup restored.');location.reload()}catch{alert('Invalid backup file.')}};r.readAsText(f)}
function restoreAuto(){const x=raw('rishu_erp_auto_backup'),d=norm(x?.data||x);if(!d.items.length&&!d.parties.length&&!d.sales.length&&!d.purchases.length)return alert('Auto backup available nahi hai.');if(confirm('Auto backup restore karein? Current data replace hoga.')){db=d;save();location.reload()}}
function settings(){const s=shop();const c=window.cloudBridge?window.cloudBridge.status():{configured:false,signedIn:false,email:''};$('app').innerHTML=layout('Shop / System & Cloud Settings',`<button class="btn" onclick="saveSettings()">Save Settings</button>`)+`<div class="card"><div class="formgrid"><div class="field wide"><label>Shop Name</label><input id="sName" value="${esc(s.name)}"></div><div class="field"><label>Mobile</label><input id="sMobile" value="${esc(s.mobile)}"></div><div class="field wide"><label>Address</label><input id="sAddress" value="${esc(s.address)}"></div></div></div>`+`<div class="card"><h3>☁️ Cloud Sync (Supabase)</h3><div class="note">Connect this ERP to a Supabase project for multi-device cloud data. Use only the publishable key in the browser; never use a service-role/secret key.</div><div class="formgrid"><div class="field wide"><label>Supabase Project URL</label><input id="sbUrl" placeholder="https://xxxx.supabase.co" value="${esc(localStorage.getItem('rishu_sb_url')||'')}"></div><div class="field wide"><label>Supabase Publishable Key</label><input id="sbKey" placeholder="sb_publishable_..." value="${esc(localStorage.getItem('rishu_sb_key')||'')}"></div><div class="field"><label>Cloud Email</label><input id="sbEmail" type="email" placeholder="you@example.com" value="${esc(localStorage.getItem('rishu_sb_email')||'')}"></div><div class="field"><label>Cloud Password</label><input id="sbPass" type="password" placeholder="Enter password"></div></div><div class="actions"><button class="btn" onclick="cloudConnect()">Connect / Sign In</button><button class="btn gray" onclick="cloudSignUp()">Create Cloud Account</button><button class="btn gray" onclick="cloudPull()">⬇ Pull Cloud</button><button class="btn gray" onclick="cloudPush()">⬆ Push Local</button><button class="btn gray" onclick="cloudLogout()">Sign Out</button></div><div id="cloudStatus" class="muted">${c.configured?(c.signedIn?'🟢 Connected: '+esc(c.email):'🟡 Configured, not signed in'):'⚪ Cloud not configured yet'}</div></div>`}
async function cloudConnect(){if(!window.cloudBridge)return alert('Cloud module not loaded.');return window.cloudBridge.connect($('sbUrl').value.trim(),$('sbKey').value.trim(),$('sbEmail').value.trim(),$('sbPass').value)}
async function cloudSignUp(){if(!window.cloudBridge)return alert('Cloud module not loaded.');return window.cloudBridge.signUp($('sbUrl').value.trim(),$('sbKey').value.trim(),$('sbEmail').value.trim(),$('sbPass').value)}
async function cloudPull(){if(!window.cloudBridge)return alert('Cloud module not loaded.');const d=await window.cloudBridge.pull();if(d){db=norm(d);localStorage.setItem(KEY,JSON.stringify(db));alert('Cloud data loaded on this device.');show('dashboard')}}
async function cloudPush(){if(!window.cloudBridge)return alert('Cloud module not loaded.');await window.cloudBridge.push(db)}
async function cloudLogout(){if(window.cloudBridge){await window.cloudBridge.logout();settings()}}
function saveSettings(){localStorage.setItem('rishu_shop_name',$('sName').value.trim()||'RISHU MEDICAL AND HEALTHCARE');localStorage.setItem('rishu_shop_mobile',$('sMobile').value.trim());localStorage.setItem('rishu_shop_address',$('sAddress').value.trim());alert('Settings saved.');show('dashboard')}
function openModal(title,html){$('modalRoot').innerHTML=`<div class="modal" onclick="if(event.target===this)closeModal()"><div class="modalbox"><div class="modalhead"><h2>${esc(title)}</h2><button class="btn gray" onclick="closeModal()">✕</button></div>${html}</div></div>`;setTimeout(()=>$('modalRoot').querySelector('input[autofocus]')?.focus(),50)}
function closeModal(){$('modalRoot').innerHTML=''}
function exportCSV(kind){let rows=[],head=[],name=kind;if(kind==='sales'){head=['Bill','Date','Party','Product','Batch','Expiry','Qty','MRP','GST','Amount'];rows=db.sales.flatMap(s=>s.lines.map(l=>[s.no,s.date,s.party,l.product,l.batch,l.exp,l.qty,l.mrp,l.gst,l.after+l.tax]))}else if(kind==='purchases'){head=['Invoice','Date','Supplier','Product','Batch','Expiry','Qty','Free','Purchase Rate','MRP','GST','Total'];rows=db.purchases.flatMap(p=>p.lines.map(l=>[p.no,p.date,p.supplier,l.product,l.batch,l.exp,l.qty,l.free,l.prate,l.mrp,l.gst,l.total2]))}else if(kind==='items'){head=['Product','Company','Salt','Barcode','Batch','Expiry','Pack','MRP','Purchase Rate','GST','Stock','Rack'];rows=db.items.map(i=>[i.product,i.company,i.salt,i.barcode,i.batch,i.exp,i.pack,i.mrp,i.rate,i.gst,i.stock,i.rack])}else{head=['Name','Type','Mobile','GSTIN','Address','Credit Limit'];rows=db.parties.map(p=>[p.name,p.type,p.mobile,p.gstin,p.address,p.creditLimit])}const csv=[head,...rows].map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');download(`Rishu_${name}_${today()}.csv`,csv,'text/csv')}
function download(name,data,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type}));a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const pages={dashboard:dashboardV10,sale,purchase,party,item,stock,reports,backup,settings,doctors,expenses,purchaseOrders,accounting,users};
Object.assign(window,{show,login,doLogin,logout,catalogPicker,renderCatalog,selectCatalog,purchaseOrders,purchaseOrderModal,savePO,deletePO,printPO,accounting,paymentModal,savePayment,users,userModal,saveUser,deleteUser,partyModal,doctorModal,saveDoctor,deleteDoctor,renderDoctors,expenseModal,saveExpense,deleteExpense,saveParty,editParty,deleteParty,itemModal,saveItem,editItem,deleteItem,filterItems,addSaleSearch,chooseItem,suggest,renderSale,saveSale,previewSale,newSale,newPurchase,addPurchaseSearch,addBlankPurchase,renderPurchase,savePurchase,previewPurchase,printSale,printPurchase,stockAdjustModal,adjustStock,salesBook,purchaseBook,dayBook,ledger,renderLedger,stockLedger,renderStockLedger,expiryReport,shareWhatsApp,exportCSV,backup,downloadBackup,restoreFile,restoreAuto,settings,saveSettings,closeModal,db,purchaseRows,saleRows,cloudConnect,cloudSignUp,cloudPull,cloudPush,cloudLogout});
window.normalizeItem=normalizeItem;window.saveERP=save;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='F2'){e.preventDefault();show('sale')}if(e.key==='F3'){e.preventDefault();show('item')}if(e.key==='F4'){e.preventDefault();show('party')}if(e.key==='F8'){e.preventDefault();show('purchase')}});
